#!/usr/bin/env python3
"""根据 headless UI 风险报告批量生成 auto-generated compat 源码和 props。"""
from __future__ import annotations

import argparse
import json
import re
from collections import Counter
from dataclasses import dataclass
from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parents[4]
DEFAULT_REPORT = (
    REPO_ROOT
    / "STS2AI"
    / "Artifacts"
    / "headless_ui_risk_scan"
    / "headless_ui_risk_scan_20260418_compiled_monsters.json"
)
GENERATED_ROOT = REPO_ROOT / "STS2AI" / "ENV" / "Sim" / "SrcCompat" / "AutoGenerated"
PROPS_FILE = GENERATED_ROOT / "headless_generated_compats.props"


@dataclass(frozen=True)
class Transform:
    name: str
    pattern: re.Pattern[str]
    replacement: str | None = None


TRANSFORMS: tuple[Transform, ...] = (
    Transform(
        "try_do_hit_stop",
        re.compile(r"\bNGame\.Instance(?:\?)?\.DoHitStop\("),
        "HeadlessVisualCompat.TryDoHitStop(",
    ),
    Transform(
        "try_screen_shake_trauma",
        re.compile(r"\bNGame\.Instance(?:\?)?\.ScreenShakeTrauma\("),
        "HeadlessVisualCompat.TryScreenShakeTrauma(",
    ),
    Transform(
        "try_screen_shake",
        re.compile(r"\bNGame\.Instance(?:\?)?\.ScreenShake\("),
        "HeadlessVisualCompat.TryScreenShake(",
    ),
    Transform(
        "try_screen_rumble",
        re.compile(r"\bNGame\.Instance(?:\?)?\.ScreenRumble\("),
        "HeadlessVisualCompat.TryScreenRumble(",
    ),
    Transform(
        "viewport_center_or_zero",
        re.compile(r"\bNGame\.Instance(?:\?)?\.GetViewportRect\(\)\.Size\s*/\s*2f\b"),
        "HeadlessVisualCompat.GetViewportCenterOrZero()",
    ),
    Transform(
        "try_add_combat_vfx",
        re.compile(r"\bNCombatRoom\.Instance(?:\?)?\.CombatVfxContainer(?:\?)?\.AddChildSafely\("),
        "HeadlessVisualCompat.TryAddCombatVfx(",
    ),
    Transform(
        "try_add_back_combat_vfx",
        re.compile(r"\bNCombatRoom\.Instance(?:\?)?\.BackCombatVfxContainer(?:\?)?\.AddChildSafely\("),
        "HeadlessVisualCompat.TryAddBackCombatVfx(",
    ),
    Transform(
        "try_add_global_ui",
        re.compile(r"\bNGame\.Instance(?:\?)?\.CurrentRunNode(?:\?)?\.GlobalUi(?:\?)?\.AddChildSafely\("),
        "HeadlessVisualCompat.TryAddGlobalUi(",
    ),
    Transform(
        "try_get_background_node",
        re.compile(r"\bNCombatRoom\.Instance(?:\?)?\.Background(?:\?)?\.GetNode<"),
        "HeadlessVisualCompat.TryGetBackgroundNode<",
    ),
    Transform(
        "try_get_creature_node",
        re.compile(r"\bNCombatRoom\.Instance(?:\?)?\.GetCreatureNode\("),
        "HeadlessVisualCompat.TryGetCreatureNode(",
    ),
    Transform(
        "try_set_fabricator_bot_fall_position",
        re.compile(r"\bFabricatorNormal\.SetBotFallPosition\("),
        "HeadlessVisualCompat.TrySetFabricatorBotFallPosition(",
    ),
)

SPECIAL_NODE_PATTERN = re.compile(
    r"\(?(?P<owner>HeadlessVisualCompat\.TryGetCreatureNode\(.+?\)|NCombatRoom\.Instance(?:\?)?\.GetCreatureNode\(.+?\)|\b[A-Za-z_][A-Za-z0-9_]*)\)?"
    r"(?:\?)?\.GetSpecialNode<(?P<generic>[^>]+)>\((?P<arg>.+?)\)"
)
INLINE_CREATURE_GLOBAL_POSITION_PATTERN = re.compile(
    r"HeadlessVisualCompat\.TryGetCreatureNode\((?P<arg>.+?)\)\.GlobalPosition\b"
)
ASSIGNMENT_RE = re.compile(
    r"\b(?:var|[A-Za-z_][A-Za-z0-9_<>,.?]*)\s+(?P<var>[A-Za-z_][A-Za-z0-9_]*)\s*=\s*(?P<expr>.+?);"
)
NULLABLE_CREATURE_HINTS = (
    "HeadlessVisualCompat.TryGetCreatureNode(",
    "NCombatRoom.Instance?.GetCreatureNode(",
)
NULLABLE_NODE_HINTS = (
    "HeadlessVisualCompat.TryGetSpecialNode<",
    "HeadlessVisualCompat.TryGetBackgroundNode<",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--report",
        type=Path,
        default=DEFAULT_REPORT,
        help="风险报告 JSON 路径。",
    )
    parser.add_argument(
        "--top",
        type=int,
        default=10,
        help="按风险频次选择前 N 个源文件。",
    )
    parser.add_argument(
        "--match",
        default="",
        help="只处理文件名或路径里包含该子串的条目。",
    )
    parser.add_argument(
        "--write-files",
        action="store_true",
        help="把生成结果写到 STS2AI/ENV/Sim/SrcCompat/AutoGenerated。",
    )
    return parser.parse_args()


def load_candidates(report_path: Path, *, top: int, match: str) -> list[tuple[Path, int]]:
    report = json.loads(report_path.read_text(encoding="utf-8"))
    counter: Counter[Path] = Counter()
    for finding in report["findings"]:
        if finding["mitigation"] not in {"add_overlay_compat", "add_src_compat"}:
            continue
        file_path = Path(finding["file"])
        if not str(file_path).startswith(str((REPO_ROOT / "src" / "Core" / "Models").resolve())):
            continue
        rel = file_path.resolve().relative_to(REPO_ROOT.resolve()).as_posix()
        if match and match.lower() not in rel.lower():
            continue
        counter[file_path.resolve()] += 1
    return counter.most_common(top)


def ensure_helpers_using(text: str) -> str:
    helper_using = "using MegaCrit.Sts2.Core.Helpers;\n"
    if helper_using in text:
        return text
    lines = text.splitlines(keepends=True)
    insert_at = 0
    while insert_at < len(lines) and lines[insert_at].startswith("using "):
        insert_at += 1
    lines.insert(insert_at, helper_using)
    return "".join(lines)


def rewrite_special_nodes(text: str) -> tuple[str, int]:
    count = 0

    def repl(match: re.Match[str]) -> str:
        nonlocal count
        count += 1
        return (
            f"HeadlessVisualCompat.TryGetSpecialNode<{match.group('generic')}>"
            f"({match.group('owner')}, {match.group('arg')})"
        )

    return SPECIAL_NODE_PATTERN.sub(repl, text), count


def rewrite_inline_creature_global_positions(text: str) -> tuple[str, int]:
    count = 0

    def repl(match: re.Match[str]) -> str:
        nonlocal count
        count += 1
        return (
            "HeadlessVisualCompat.GetGlobalPositionOrZero("
            f"HeadlessVisualCompat.TryGetCreatureNode({match.group('arg')}))"
        )

    return INLINE_CREATURE_GLOBAL_POSITION_PATTERN.sub(repl, text), count


def collect_nullable_vars(text: str) -> dict[str, str]:
    nullable_vars: dict[str, str] = {}
    for line in text.splitlines():
        match = ASSIGNMENT_RE.search(line)
        if match is None:
            continue
        var_name = match.group("var")
        expr = match.group("expr")
        if any(hint in expr for hint in NULLABLE_CREATURE_HINTS):
            nullable_vars[var_name] = "creature"
            continue
        if any(hint in expr for hint in NULLABLE_NODE_HINTS):
            nullable_vars[var_name] = "node"
    return nullable_vars


def rewrite_nullable_var_accesses(text: str) -> tuple[str, Counter[str]]:
    counts: Counter[str] = Counter()
    nullable_vars = collect_nullable_vars(text)
    for var_name, kind in sorted(nullable_vars.items()):
        escaped = re.escape(var_name)

        add_child_pattern = re.compile(
            rf"(?m)^(?P<indent>\s*){escaped}\.AddChildSafely\((?P<child>.+?)\);$"
        )
        text, num = add_child_pattern.subn(
            lambda match: (
                f"{match.group('indent')}HeadlessVisualCompat.TryAddChild"
                f"({var_name}, {match.group('child')});"
            ),
            text,
        )
        if num:
            counts["try_add_child"] += num

        if kind == "creature":
            body_node_pattern = re.compile(
                rf"\b{escaped}\.Visuals\.GetCurrentBody\(\)\.GetNode<(?P<generic>[^>]+)>\((?P<arg>.+?)\)"
            )
            text, num = body_node_pattern.subn(
                lambda match: (
                    f"HeadlessVisualCompat.TryGetCurrentBodyNode<{match.group('generic')}>"
                    f"({var_name}, {match.group('arg')})"
                ),
                text,
            )
            if num:
                counts["try_get_current_body_node"] += num

            text, num = re.subn(
                rf"\b{escaped}\.Visuals\.GetCurrentBody\(\)\.Scale\.X\b",
                f"HeadlessVisualCompat.GetCurrentBodyScaleXOrOne({var_name})",
                text,
            )
            if num:
                counts["current_body_scale_x_or_one"] += num

            text, num = re.subn(
                rf"\b{escaped}\.Visuals\.GetCurrentBody\(\)\.Scale\b",
                f"HeadlessVisualCompat.GetCurrentBodyScaleOrOne({var_name})",
                text,
            )
            if num:
                counts["current_body_scale_or_one"] += num

            text, num = re.subn(
                rf"\b{escaped}\.Body\.Scale\b",
                f"HeadlessVisualCompat.GetBodyScaleOrOne({var_name})",
                text,
            )
            if num:
                counts["body_scale_or_one"] += num

        position_offset_pattern = re.compile(
            rf"(?m)^(?P<indent>\s*){escaped}\.Position\s*\+=\s*(?P<expr>.+?);$"
        )
        text, num = position_offset_pattern.subn(
            lambda match: (
                f"{match.group('indent')}HeadlessVisualCompat.TryOffsetPosition"
                f"({var_name}, {match.group('expr')});"
            ),
            text,
        )
        if num:
            counts["try_offset_position"] += num

        position_set_pattern = re.compile(
            rf"(?m)^(?P<indent>\s*){escaped}\.Position\s*=\s*(?P<expr>.+?);$"
        )
        text, num = position_set_pattern.subn(
            lambda match: (
                f"{match.group('indent')}HeadlessVisualCompat.TrySetPosition"
                f"({var_name}, {match.group('expr')});"
            ),
            text,
        )
        if num:
            counts["try_set_position"] += num

        global_position_set_pattern = re.compile(
            rf"(?m)^(?P<indent>\s*){escaped}\.GlobalPosition\s*=\s*(?P<expr>.+?);$"
        )
        text, num = global_position_set_pattern.subn(
            lambda match: (
                f"{match.group('indent')}HeadlessVisualCompat.TrySetGlobalPosition"
                f"({var_name}, {match.group('expr')});"
            ),
            text,
        )
        if num:
            counts["try_set_global_position"] += num

        text, num = re.subn(
            rf"\b{escaped}\.GlobalPosition\b",
            f"HeadlessVisualCompat.GetGlobalPositionOrZero({var_name})",
            text,
        )
        if num:
            counts["global_position_or_zero"] += num

    return text, counts


def apply_transforms(text: str) -> tuple[str, Counter[str]]:
    counts: Counter[str] = Counter()
    for transform in TRANSFORMS:
        updated, num = transform.pattern.subn(transform.replacement or "", text)
        if num:
            counts[transform.name] += num
            text = updated

    text, special_count = rewrite_special_nodes(text)
    if special_count:
        counts["try_get_special_node"] += special_count

    text, global_position_count = rewrite_inline_creature_global_positions(text)
    if global_position_count:
        counts["inline_global_position_or_zero"] += global_position_count

    text, nullable_counts = rewrite_nullable_var_accesses(text)
    counts.update(nullable_counts)

    if not counts:
        return text, counts

    text = ensure_helpers_using(text)
    header = (
        "// AUTO-GENERATED FILE. Source of truth is upstream src/ plus the\n"
        "// generator script STS2AI/ENV/Sim/scripts/generate_headless_model_compats.py.\n"
        "// Safe to regenerate; manual edits will be overwritten.\n\n"
    )
    if not text.startswith("// AUTO-GENERATED FILE."):
        text = header + text
    return text, counts


def target_generated_path(source_path: Path) -> Path:
    rel = source_path.resolve().relative_to((REPO_ROOT / "src").resolve())
    return GENERATED_ROOT / rel


