def write_generated_props(generated_files: list[Path]) -> None:
    lines = ["<Project>", "  <ItemGroup>"]
    for generated_path in sorted(generated_files):
        source_rel = generated_path.resolve().relative_to(GENERATED_ROOT.resolve()).as_posix()
        upstream_rel = source_rel.replace("/", "\\")
        lines.append(
            f'    <Compile Remove="$(MSBuildThisFileDirectory)..\\..\\..\\..\\..\\src\\{upstream_rel}" />'
        )
    lines.append(
        '    <Compile Include="$(MSBuildThisFileDirectory)**\\*.cs" '
        'Link="SrcCompat\\AutoGenerated\\%(RecursiveDir)%(Filename)%(Extension)" />'
    )
    lines.append("  </ItemGroup>")
    lines.append("</Project>")
    GENERATED_ROOT.mkdir(parents=True, exist_ok=True)
    PROPS_FILE.write_text("\n".join(lines) + "\n", encoding="utf-8")


def clean_generated_root() -> None:
    if not GENERATED_ROOT.exists():
        return
    for path in sorted(GENERATED_ROOT.rglob("*"), reverse=True):
        if path.is_file():
            path.unlink()
        elif path.is_dir():
            try:
                path.rmdir()
            except OSError:
                pass


def main() -> int:
    args = parse_args()
    candidates = load_candidates(args.report.resolve(), top=args.top, match=args.match)
    if not candidates:
        print("[generate_headless_model_compats] no candidates")
        return 0

    generated_paths: list[Path] = []
    generated_contents: dict[Path, str] = {}
    for source_path, score in candidates:
        output_path = target_generated_path(source_path)
        text = source_path.read_text(encoding="utf-8")
        rewritten, counts = apply_transforms(text)
        summary = ", ".join(f"{name}={count}" for name, count in sorted(counts.items())) or "no-op"
        print(f"[candidate] score={score:>2} src={source_path}")
        print(f"           dst={output_path}")
        print(f"           transforms: {summary}")
        if not counts:
            continue
        generated_paths.append(output_path)
        generated_contents[output_path] = rewritten

    if args.write_files:
        clean_generated_root()
        helper_path = GENERATED_ROOT / "Core" / "Helpers" / "HeadlessVisualCompat.cs"
        helper_path.parent.mkdir(parents=True, exist_ok=True)
        helper_path.write_text(HELPER_SOURCE, encoding="utf-8")
        for output_path, rewritten in generated_contents.items():
            output_path.parent.mkdir(parents=True, exist_ok=True)
            output_path.write_text(rewritten, encoding="utf-8")
        write_generated_props(generated_paths)
        print(f"[generate_headless_model_compats] wrote generated sources to: {GENERATED_ROOT}")
        print(f"[generate_headless_model_compats] wrote props file: {PROPS_FILE}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
